section.programlisting:
{
  product: {
    id: 'SLES',
    registrationCode: 'YOUR-SLES-REGISTRATION-CODE',
  },
  user: {
    fullName: 'Monsignore Tux',
    password: 'linux',
    userName: 'tux',
  },
  scripts: {
    post: [
      {
        name: 'enable-kdump',
        chroot: true,
        content: |||
          #!/usr/bin/bash
          zypper -n in kdump
          systemctl enable kdump-commandline.service
          systemctl enable kdump.service
          kdumptool commandline -u
        |||,
      },
    ],
  },
}

